// Blog.jsx

import React, { useEffect, useState } from 'react';
import './Blog.css';
import { Link } from 'react-router-dom';
import axios from 'axios';

function Blog() {
  const [articulos, setArticulos] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchArticulos = async () => {
      try {
        // Ruta pendiente de crear en el backend
        const response = await axios.get('http://localhost:3000/api/blog/articulos');
        setArticulos(response.data);
      } catch (err) {
        setError('No se pudieron cargar los artículos.');
      } finally {
        setIsLoading(false);
      }
    };
    fetchArticulos();
  }, []);

  if (isLoading) {
    return (
      <div className="container">
        <div className="header">
          <h1 className="header-title">Cargando artículos...</h1>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="container">
        <div className="header">
          <h1 className="header-title">{error}</h1>
        </div>
      </div>
    );
  }

  return (
    <div className="container">
      <div className="header">
        <h1 className="header-title">Explora nuestros artículos ({articulos.length})</h1>
      </div>

      <div className="articles-grid">
        {articulos.map((articulo) => (
          <article key={articulo.id_post} className="article-card">
            <div className="article-image">
              {articulo.imagen_blog && (
                <img
                  src={`http://localhost:3000/uploads/blog/${articulo.imagen_blog}`}
                  alt={articulo.titulo}
                  className="blog-img"
                />
              )}
            </div>
            <div className="article-content" style={{ background: '#2d2320', color: '#D68F48', padding: '18px 16px 12px 16px', borderBottomLeftRadius: '16px', borderBottomRightRadius: '16px' }}>
              <h2 className="article-title" style={{ color: '#D68F48', fontWeight: 'bold', fontSize: '1.3rem', marginBottom: '10px' }}>{articulo.titulo}</h2>
              <div className="article-meta" style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '8px' }}>
                <div className="author-info" style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                  <div className="author-icon" style={{ color: '#D68F48', fontSize: '1.1rem' }}>👤</div>
                  <span className="author-name" style={{ color: '#D68F48', fontWeight: 'bold' }}>{articulo.autor}</span>
                </div>
                <span className="publish-date" style={{ color: '#D68F48', fontSize: '0.95rem' }}>
                  {articulo.fecha_publicacion
                    ? new Date(articulo.fecha_publicacion).toLocaleDateString('es-CO', { day: 'numeric', month: 'long', year: 'numeric' })
                    : 'Sin fecha'}
                </span>
              </div>
              <Link to={`/articulo/${articulo.id_post}`}> <button className="read-more-btn">Leer Más &gt;</button></Link>
            </div>
          </article>
        ))}
      </div>
    </div>
  );
}

export default Blog;
